# Generate placeholder robot icons for MR600-Bot extension
# Run this script once to create the icon files

$iconDir = Join-Path (Split-Path $PSCommandPath -Parent) "icons"
if (!(Test-Path $iconDir)) { New-Item -ItemType Directory $iconDir -Force | Out-Null }

# Simple blue robot emoji PNG (16x16, 48x48, 128x128) - stored as base64
$icon16Base64 = "iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAYAAAAf8/9hAAAAAXNSR0IArs4c6QAAADpJREFUOI1jYBgFo2AUjIJRMApGwSgYhgEjIyMDEwMLEwMTEwMDAwMxwMjICCxkZABiRkYGBkZmJgYGBgZGAE/H9x6p5qjJAAAAAElFTkSuQmCC"
$icon48Base64 = ""
$icon128Base64 = ""

# Write the PNG files
[System.IO.File]::WriteAllBytes((Join-Path $iconDir "icon16.png"), [System.Convert]::FromBase64String($icon16Base64))
[System.IO.File]::WriteAllBytes((Join-Path $iconDir "icon48.png"), [System.Convert]::FromBase64String($icon48Base64))
[System.IO.File]::WriteAllBytes((Join-Path $iconDir "icon128.png"), [System.Convert]::FromBase64String($icon128Base64))

Write-Host "✅ Icon files created successfully in $iconDir"
